<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Icon } from '@iconify/vue'
import { ElMessageBox } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import DatabaseConnectionDrawer from '@/components/DatabaseConnectionDrawer.vue'
import { api } from '@/api/client'
import type { DatabaseConnection, DatabaseDriver, DatabaseProbe, DatabaseTypeProfile, Project } from '@/types/domain'
import { userFacingError } from '@/utils/displayLabels'
const rows = ref<DatabaseConnection[]>([]), types = ref<DatabaseTypeProfile[]>([]), drivers = ref<DatabaseDriver[]>([]), projects = ref<Project[]>([])
const cursor = ref<string | null>(null), loading = ref(false), saving = ref(false), error = ref(''), editing = ref(false), selected = ref<DatabaseConnection | null>(null)
const query = ref(''), type = ref(''), state = ref('AVAILABLE'), probe = ref<Record<string, DatabaseProbe>>({}), testing = ref<string | null>(null)
const typeLabels = { MYSQL: 'MySQL', OPENGAUSS: 'openGauss', GAUSSDB: 'GaussDB', GOLDENDB: 'GoldenDB（历史配置）', DAMENG: '达梦', ORACLE: 'Oracle', DB2: 'DB2', SQLSERVER: 'SQL Server' }
const activeId = ref('')
const active = computed(() => rows.value.find(row => row.id === activeId.value) ?? rows.value[0])
const testErrors = ref<Record<string, string>>({})
const stateLabel = (row: DatabaseConnection) => row.archived ? '已归档' : row.enabled ? '已启用' : '已停用'
const projectNames = (row: DatabaseConnection) => row.projectIds.map(id => projects.value.find(p => p.id === id)?.name ?? '已登记项目')
let generation = 0
async function load(more = false) {
  const current = ++generation; loading.value = true; error.value = ''
  if (!more) { rows.value = []; cursor.value = null; probe.value = {}; testErrors.value = {} }
  try { const result = await api.getDatabaseConnections(more ? cursor.value ?? undefined : undefined, { query: query.value, type: type.value, state: state.value }); if (current === generation) { rows.value = more ? [...rows.value, ...result.items] : result.items; cursor.value = result.nextCursor ?? null } }
  catch (cause) { if (current === generation) error.value = userFacingError(cause, '连接列表读取失败，请重试') }
  finally { if (current === generation) loading.value = false }
}
watch([type, state], () => { void load() })
function edit(row: DatabaseConnection | null = null) { selected.value = row; editing.value = true }
async function update(row: DatabaseConnection, archive: boolean) {
  if (archive) { try { await ElMessageBox.confirm(`归档“${row.name}”后，新任务不能发现此连接。已冻结任务仍使用原授权。`, '归档连接', { confirmButtonText: '归档', cancelButtonText: '取消' }) } catch { return } }
  saving.value = true; error.value = ''
  try { await api.saveDatabaseConnection(row.id, { ...row, password: null, enabled: archive ? false : !row.enabled, archived: archive || row.archived }); await load() }
  catch (cause) { error.value = userFacingError(cause, '配置未更新，请刷新后重试') }
  finally { saving.value = false }
}
async function test(row: DatabaseConnection) {
  if (testing.value) return
  testing.value = row.id; delete testErrors.value[row.id]; delete probe.value[row.id]
  const current = generation
  try { const result = await api.testDatabaseConnection(row.id); if (current === generation) probe.value[row.id] = result }
  catch (cause) { if (current === generation) testErrors.value[row.id] = userFacingError(cause, '连接检查失败，请检查驱动、凭据及网络') }
  finally { testing.value = null }
}
function driverState(row: DatabaseConnection) { return row.config.driverProfile ? '内置驱动' : drivers.value.some(d => d.filename === row.config.driverFile) ? '驱动已安装' : '历史驱动缺失' }
onMounted(() => {
  void load()
  void Promise.all([api.getDatabaseTypes(), api.getDatabaseDrivers(), api.getProjects()]).then(([t, d, p]) => { types.value = t; drivers.value = d; projects.value = p }).catch(cause => { error.value = userFacingError(cause, '类型或项目清单读取失败，请刷新页面') })
})
</script>
<template>
  <PageHeader eyebrow="系统" title="数据库"><template #actions><el-button :loading="loading" @click="load()">刷新</el-button><el-button type="primary" :disabled="!types.length" @click="edit()"><Icon icon="lucide:plus" width="15" />新增连接</el-button></template></PageHeader>
  <main id="main-content" class="content database-page" tabindex="-1">
    <div class="database-intro"><div><p class="eyebrow">数据连接</p><h2>项目的数据访问空间</h2><p>统一管理连接、项目授权与只读访问范围。</p></div><span class="mode-badge"><Icon icon="lucide:shield-check" width="16" />只读访问</span></div>
    <form class="filters" @submit.prevent="load()"><el-input v-model="query" placeholder="搜索连接名称或主机" aria-label="搜索数据库" clearable @clear="load()"><template #prefix><Icon icon="lucide:search" /></template></el-input><el-select v-model="type" aria-label="筛选数据库类型" placeholder="全部类型"><el-option value="" label="全部类型" /><el-option v-for="(label, value) in typeLabels" :key="value" :value="value" :label="label" /></el-select><el-select v-model="state" aria-label="筛选连接状态"><el-option value="AVAILABLE" label="未归档" /><el-option value="ENABLED" label="已启用" /><el-option value="DISABLED" label="已停用" /><el-option value="ARCHIVED" label="已归档" /><el-option value="ALL" label="全部状态" /></el-select><el-button native-type="submit" :loading="loading">搜索</el-button></form>
    <div v-if="error" role="alert" class="error-banner"><span>{{ error }}</span><el-button @click="load()">重新加载</el-button></div>
    <section v-if="loading && !rows.length" class="card empty" role="status">正在读取连接…</section>
    <section v-else-if="!rows.length && !error" class="card empty"><div class="empty-icon"><Icon icon="lucide:database" width="32" /></div><h2>{{ query || type || state !== 'AVAILABLE' ? '没有匹配的连接' : '连接你的第一套数据库' }}</h2><p>将数据库绑定到项目，让任务按需读取表结构和业务数据。</p><div class="supported"><span v-for="item in types" :key="item.id">{{ item.label }}</span></div><el-button type="primary" :disabled="!types.length" @click="edit()">新增数据库连接</el-button></section>
    <div v-else-if="rows.length" class="database-workspace" :aria-busy="loading">
      <aside class="card connection-catalog" aria-label="数据库连接目录">
        <div class="catalog-heading"><strong>连接目录</strong><span>已加载 {{ rows.length }} 项</span></div>
        <div class="connection-list"><button v-for="row in rows" :key="row.id" type="button" :class="['connection-item', { selected: active?.id === row.id }]" :aria-pressed="active?.id === row.id" @click="activeId = row.id">
          <span class="database-icon"><Icon icon="lucide:database" width="20" /></span><span class="connection-summary"><strong>{{ row.name }}</strong><small>{{ typeLabels[row.config.type] }} · {{ row.config.database }}</small><small>{{ row.config.host }}:{{ row.config.port }}</small></span><span :class="['status-dot', { enabled: row.enabled && !row.archived }]" :aria-label="stateLabel(row)" /></button></div>
        <el-button v-if="cursor" :loading="loading" class="load-more" @click="load(true)">加载更多</el-button>
      </aside>
      <section v-if="active" class="card connection-detail" aria-label="连接详情">
        <header class="detail-heading"><div><p class="eyebrow">{{ typeLabels[active.config.type] }}</p><h2>{{ active.name }}</h2><span :class="['state-pill', { enabled: active.enabled && !active.archived }]">{{ stateLabel(active) }}</span></div><el-button :disabled="saving || active.archived || !types.some(t => t.type === active!.config.type)" @click="edit(active)"><Icon icon="lucide:settings-2" width="15" />编辑连接</el-button></header>
        <div class="detail-metrics"><div><small>授权项目</small><strong>{{ active.projectIds.length }} <span>个</span></strong></div><div><small>访问范围</small><strong>{{ active.config.schemas.length }} <span>个 schema / 数据库</span></strong></div><div><small>查询限额</small><strong>{{ active.config.maxRows }} <span>行 / {{ active.config.timeoutSeconds }} 秒</span></strong></div></div>
        <section class="detail-section"><h3><Icon icon="lucide:server" width="16" />连接信息</h3><dl><div class="full"><dt>访问地址</dt><dd class="address">{{ active.config.jdbcUrl || `${active.config.host}:${active.config.port}/${active.config.database}` }}</dd></div><div><dt>数据库</dt><dd>{{ active.config.database }}</dd></div><div><dt>用户名</dt><dd>{{ active.config.username }}</dd></div><div><dt>驱动</dt><dd>{{ driverState(active) }}</dd></div><div><dt>凭据</dt><dd>{{ active.passwordConfigured ? '已配置' : '未配置' }}</dd></div></dl></section>
        <section class="detail-section"><h3><Icon icon="lucide:folder-key" width="16" />项目与访问范围</h3><div class="authorization-row"><span>授权项目</span><div class="chips"><span v-for="(name, index) in projectNames(active)" :key="index">{{ name }}</span><p v-if="!active.projectIds.length" class="muted">尚未绑定项目，任务暂时无法使用此连接。</p></div></div><div class="authorization-row"><span>允许范围</span><div class="chips schema"><span v-for="name in active.config.schemas" :key="name">{{ name }}</span></div></div></section>
        <section class="detail-section connection-health"><div class="health-heading"><h3><Icon icon="lucide:activity" width="16" />连接检查</h3><el-button :loading="testing === active.id" :disabled="testing !== null" @click="test(active)">测试连接</el-button></div><div v-if="testErrors[active.id]" class="test-error" role="alert"><strong>连接检查失败</strong><p>{{ testErrors[active.id] }}</p></div><div v-else-if="probe[active.id]" class="probe" role="status"><strong>连接成功 · {{ probe[active.id]?.sessionReadOnly ? '只读标记已确认' : probe[active.id]?.readOnlyEnforced ? '只读权限已检查' : '只读控制未通过' }}</strong><p>{{ probe[active.id]?.serverProduct }} {{ probe[active.id]?.serverVersion }}</p><p>{{ probe[active.id]?.detail }}</p></div><p v-else class="muted">{{ testing === active.id ? '正在检查网络、登录与只读访问…' : '尚未检查此连接，点击“测试连接”获取当前结果。' }}</p><small class="compatibility">完整兼容性：待现场版本联调</small></section>
        <footer class="detail-footer"><p>配置变更供新会话使用，历史任务保留冻结配置。</p><div><el-button v-if="!active.archived && (active.enabled || types.some(t => t.type === active!.config.type))" :disabled="saving" @click="update(active, false)">{{ active.enabled ? '停用连接' : '启用连接' }}</el-button><el-button v-if="!active.archived" type="danger" plain :disabled="saving" @click="update(active, true)">归档</el-button></div></footer>
      </section>
    </div>
    <DatabaseConnectionDrawer v-model="editing" :row="selected" :types="types" :projects="projects" @saved="load()" />
  </main>
</template>
<style scoped>
.database-intro{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.database-intro h2{font-size:22px;margin:7px 0 10px}.database-intro p:not(.eyebrow){font-size:13px;color:var(--color-text-secondary);margin:0}.mode-badge{display:flex;align-items:center;gap:7px;color:var(--color-accent-cyan);border:1px solid var(--color-border-default);border-radius:20px;padding:8px 12px;font-size:12px;white-space:nowrap}.filters{display:flex;gap:12px;margin-bottom:24px}.filters>.el-input{flex:1}.filters>.el-select{width:150px}.database-workspace{display:grid;grid-template-columns:minmax(260px,320px) minmax(0,1fr);gap:20px;align-items:start}.connection-catalog{padding:8px;min-width:0}.catalog-heading{display:flex;justify-content:space-between;gap:8px;padding:16px 12px;font-size:13px}.catalog-heading>span{font-size:11px;color:var(--color-text-muted)}.connection-list{display:grid;gap:6px}.connection-item{display:flex;align-items:center;gap:12px;width:100%;padding:16px 12px;background:transparent;border:1px solid transparent;border-radius:calc(var(--radius-control) + 4px);color:var(--color-text-primary);text-align:left;cursor:pointer;font:inherit}.connection-item:hover{background:var(--color-bg-elevated)}.connection-item.selected{background:var(--color-bg-elevated);border-color:var(--color-accent-cyan)}.connection-item:focus-visible{outline:2px solid var(--color-accent-cyan);outline-offset:2px}.database-icon{display:grid;place-items:center;flex-shrink:0;width:38px;height:42px;border-radius:calc(var(--radius-control) + 3px);background:var(--color-bg-surface);color:var(--color-accent-cyan)}.connection-summary{flex:1;min-width:0;display:grid;gap:6px;overflow-wrap:anywhere}.connection-summary strong{font-size:13px}.connection-summary small{font-size:11px;color:var(--color-text-secondary);line-height:1.5}.status-dot{width:6px;height:6px;border-radius:50%;background:var(--color-text-muted);flex-shrink:0}.status-dot.enabled{background:var(--color-success)}.connection-detail{padding:28px;min-width:0}.detail-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}.detail-heading h2{margin:6px 0 12px;font-size:22px;overflow-wrap:anywhere}.state-pill{display:inline-block;font-size:11px;color:var(--color-text-muted);padding:4px 9px;border:1px solid var(--color-border-default);border-radius:20px}.state-pill.enabled{color:var(--color-success)}.detail-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;padding:24px 0;margin-top:12px;border-bottom:1px solid var(--color-border-default)}.detail-metrics>div{display:grid;gap:9px}.detail-metrics small,dt{font-size:12px;color:var(--color-text-muted)}.detail-metrics strong{font-size:21px;font-variant-numeric:tabular-nums}.detail-metrics strong span{font-size:11px;font-weight:400;color:var(--color-text-secondary)}.detail-section{padding:24px 0;border-bottom:1px solid var(--color-border-default)}h3{display:flex;align-items:center;gap:8px;margin:0 0 20px;font-size:13px}h3 svg{color:var(--color-text-secondary)}dl{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:0}dl>div{min-width:0}.full{grid-column:1/-1}dd{margin:8px 0 0;font-size:13px;line-height:1.6;overflow-wrap:anywhere}.address{font-family:var(--font-mono);font-size:12px;background:var(--color-bg-elevated);border:1px solid var(--color-border-default);border-radius:calc(var(--radius-control) + 2px);padding:12px}.authorization-row{display:grid;grid-template-columns:78px minmax(0,1fr);gap:14px;margin-top:16px;align-items:start}.authorization-row>span{font-size:12px;color:var(--color-text-muted);padding-top:5px}.chips{display:flex;flex-wrap:wrap;gap:8px}.chips>span{padding:5px 9px;border:1px solid var(--color-border-default);border-radius:var(--radius-control);font-size:12px;overflow-wrap:anywhere;max-width:100%}.schema>span{font-family:var(--font-mono);color:var(--color-accent-cyan)}.muted,.probe p,.test-error p{font-size:12px;line-height:1.7;margin:0;color:var(--color-text-secondary)}.health-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.health-heading h3{margin:0}.compatibility{display:block;margin-top:12px;color:var(--color-text-muted);font-size:11px}.probe,.test-error{font-size:13px;padding:14px;border-radius:calc(var(--radius-control) + 2px);background:var(--color-bg-elevated);border-left:3px solid var(--color-success)}.probe p,.test-error p{margin-top:8px}.test-error{border-color:var(--color-task-danger)}.detail-footer{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:20px;flex-wrap:wrap}.detail-footer p{font-size:11px;color:var(--color-text-muted);line-height:1.6;margin:0}.detail-footer>div{display:flex;gap:8px}.detail-footer .el-button{margin:0}.empty{display:grid;justify-items:center;text-align:center;padding:58px 24px}.empty-icon{color:var(--color-accent-cyan);margin-bottom:18px}.empty h2{font-size:20px;margin:0 0 12px}.empty p{font-size:13px;color:var(--color-text-secondary);margin:0}.supported{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;margin:28px 0}.supported>span{border:1px solid var(--color-border-default);border-radius:calc(var(--radius-control) + 2px);padding:10px 16px;font-size:12px}.error-banner{display:flex;align-items:center;justify-content:space-between;gap:16px;color:var(--color-task-danger);padding:16px;margin-bottom:20px;border:1px solid var(--color-border-default);border-radius:calc(var(--radius-control) + 2px)}.load-more{width:100%;margin-top:12px}@media(max-width:1100px){.database-workspace{grid-template-columns:minmax(220px,260px) minmax(0,1fr)}.connection-detail{padding:20px}}@media(max-width:850px){.database-workspace{grid-template-columns:1fr}.connection-list{grid-template-columns:repeat(2,minmax(0,1fr))}.detail-heading h2{font-size:20px}}@media(max-width:600px){.filters{flex-wrap:wrap}.filters>.el-input{flex-basis:100%}.filters>.el-select{flex:1;min-width:110px}.mode-badge{display:none}.database-intro